\label{ass:powerlaw}
There are constants $0<c_{\mathrm{sp}}\le C_{\mathrm{sp}}$ and $\beta>1$ such
that
\begin{equation}\label{eq:powerlaw}
 c_{\mathrm{sp}}\,i^{-\beta}\;\le\;\sigma_i^2\;\le\;C_{\mathrm{sp}}\,i^{-\beta},
 \qquad i=1,\ldots,d.
\end{equation}

\label{def:truncated-class}
For $K\le d$, $\eta>0$ and a probability law $p$ on $\mathbb{R}^K$, the truncated
sampler is the law
\begin{equation}\label{eq:output-law}
 \widetilde p^\eta
 =\bigl(p*\mathcal{N}(0,\eta^2I_K)\bigr)\otimes\mathcal{N}(0,\eta^2I_{d-K}),
\end{equation}
written in the coordinates of the basis $V$. They are compared with the
smoothed data law, expressed in the same coordinates,
\begin{equation}\label{eq:smoothed-target}
 q^\eta:=q*\mathcal{N}(0,\eta^2I_d)=\mathrm{Law}(X+\eta Z'),
\end{equation}
where $Z'\sim\mathcal{N}(0,I_d)$ is independent of $X$.
The ideal truncated sampler is the choice $p=q_K$; we denote its law by
$\widetilde q_K^{\,\eta}$.

\label{thm:convergence}
Let Assumption~\ref{ass:powerlaw} hold, let $K\le d_{\mathrm{eff}}^{\sigma}$,
use the Wiener-gain rates \eqref{eq:wiener-rates}, and let
Assumptions~\ref{ass:lipschitz}-\ref{ass:finite-kl} hold. If
\begin{equation}\label{eq:small-step-cor2}
 \delta\le\min\Bigl\{\frac18,\ \frac1{128\sqrt{\kappa_0}\,L\sigma^2}\Bigr\},
\end{equation}
then, for a constant $C'$ that depends only on $\beta$ and $\kappa_0$,
\begin{align}
 \mathrm{TV}(p,q_K)
 &\le e^{-\lambda_\star T}\sqrt{\tfrac12\mathrm{KL}(q_K\|\gamma_K)}
 \label{eq:tv-cor2}\\
 &\quad+C'\sigma\sqrt T\Bigl(
  \varepsilon_{\mathrm{score},\Lambda}
  +L\sigma\sqrt{\lambda_0\delta K}
 \nonumber\\
 &\qquad
  +L\delta\sqrt{\lambda_0C_{\mathrm{sp}}\zeta(\beta)+\lambda_0\sigma^2K}
 \nonumber\\
 &\qquad
  +(1+L\sigma^2)\sqrt L\,\delta\sqrt{\lambda_0K}
 \Bigr).
 \nonumber
\end{align}
In particular, if
$\varepsilon_{\mathrm{score},\Lambda}\le c_1\varepsilon/(\sigma\sqrt T)$ for a
small universal constant $c_1$ and
\[
 T\ge\lambda_\star^{-1}\log\bigl(2\sqrt{\mathrm{KL}(q_K\|\gamma_K)/2}\,/\varepsilon\bigr),
\]
then $N=\widetilde O(K/\varepsilon^2)$ steps on a uniform grid give
$\mathrm{TV}(p,q_K)\le\varepsilon$. Here $\widetilde O$ hides logarithmic factors and
the constants $\lambda_0,\sigma,L,\beta,\kappa_0$, but not $K$ or $d$.

\label{lem:sharp-residual}
\label{prop:residual-kl-sharpness}
For every $1\le K<d$ and $\eta>0$,
\begin{equation}\label{eq:sharp-kl}
 \mathrm{KL}\bigl(\widetilde q_K^{\,\eta}\,\|\,q^\eta\bigr)
 =\frac12\sum_{i>K}\Bigl[\log(1+x_i)-\frac{x_i}{1+x_i}\Bigr]
 =\frac12\sum_{i>K}\bigl[-g_i-\log(1-g_i)\bigr]
 \le\frac14\sum_{i>K}\frac{x_i^2}{1+x_i}.
\end{equation}
If $x_i\le1$ for all $i>K$, then also
$\mathrm{KL}(\widetilde q_K^{\,\eta}\|q^\eta)\ge\frac1{16}\sum_{i>K}x_i^2$.
Moreover, with $S:=\sum_{i>K}\min\{x_i^2,1\}$,
\begin{equation}\label{eq:tv-lower}
 \frac12\min\Bigl\{1,\ \frac{S}{35}\Bigr\}
 \;\le\;
 \mathrm{TV}\bigl(\widetilde q_K^{\,\eta},q^\eta\bigr)
 \;\le\;
 \Bigl(\frac18\sum_{i>K}\frac{x_i^2}{1+x_i}\Bigr)^{1/2}.
\end{equation}

\label{ass:second_moment}
$m_{2,r}^2:=\mathbb{E}_{U\sim q_r}\|U\|^2<\infty$. Under
Assumption~\ref{ass:powerlaw} with $r=K$, $m_{2,K}^2\le C_{\mathrm{sp}}\zeta(\beta)$.

\label{thm:tv-trace}
Assume Assumptions~\ref{ass:lipschitz}, \ref{ass:second_moment}, \ref{ass:score_error},
\ref{ass:girsanov} and~\ref{ass:finite-kl} in $\mathbb{R}^r$, with the weighted Fisher bound $\mathbb
E_{U\sim q_{r,t}}\|\nabla\log q_{r,t}(U)\|_\Lambda^2\le C_F\operatorname{tr}(\Lambda)$
from Lemma~\ref{lem:fisher} ($C_F=L$). As in
Theorem~\ref{thm:tv-dim}, we additionally assume that the weighted
one-step score-perturbation bound of
Lemma~\ref{lem:trace_aware_weighted} applies uniformly to the
marginals $q_{r,t}$, $t\in[0,T]$; this is the only regularity used
beyond Assumption~\ref{ass:lipschitz}. Let
$\kappa:=\lambda_{\max}/\lambda_{\min}$; suppose $\lambda_{\max}
\Delta\tau_{\max}\le1$ and $\delta\le\min\{\tfrac18,
\tfrac{1}{128\sqrt\kappa\,L\sigma^2}\}$. Then there is a constant $C(\kappa)=O(\sqrt\kappa)$
with
\begin{align*}
&\mathrm{TV}(p_{\mathrm{out}},q_r) \le e^{-\lambda_{\min}T}\sqrt{\tfrac12\mathrm{KL}(q_r\|\gamma_r)}
\nonumber\\
&\quad+ C(\kappa)\sigma\sqrt T\Big(\varepsilon_{\mathrm{score},\Lambda}
+ L\delta\sqrt{m_{2,\Lambda}^2+\sigma^2\operatorname{tr}(\Lambda)}
+ (1+L\sigma^2)\sqrt{C_F}\,\delta\sqrt{\operatorname{tr}(\Lambda)}
+ L\sigma\sqrt{\delta\operatorname{tr}(\Lambda)}\Big),
\end{align*}
where $m_{2,\Lambda}^2:=\mathbb E_{U\sim q_r}\|U\|_\Lambda^2$ and
$\varepsilon_{\mathrm{score},\Lambda}^2$ is defined as in
Assumption~\ref{ass:score_error}.

\label{lem:active-sigma}
Let $q=\mathcal{N}(0,C)$ with the exact power law \eqref{eq:powerlaw2}, let
$1\le K\le d_{\mathrm{eff}}^{\sigma}$, use the Wiener-gain rates, exact scores and a uniform grid, and
assume $N\ge128\sqrt2\,\lambda_0T$. Then, with $C_0=C_0(2)$ the constant of
Corollary~\ref{cor:topK},
\[
 \mathrm{TV}(p,q_K)
 \le e^{-\lambda_0T/2}\frac{\sqrt{C_{\mathrm{sp}}\zeta(\beta)}}{2\sigma}
 +C_0\Bigl(\lambda_0T\sqrt{\tfrac KN}
 +3\lambda_0^{3/2}T^{3/2}\frac{\sqrt K}{N}
 +\lambda_0^{3/2}T^{3/2}\frac{\sqrt{C_{\mathrm{sp}}\zeta(\beta)}}{\sigma N}\Bigr).
\]

\label{ass:sufficient_data}
Fix \(K_{\max}\le d_{\mathrm{eff}}^{\sigma}\) and \(\varepsilon>0\). Assume that
the number of independent training patches satisfies
\[
 n_{\mathrm{patch}}
 \ge
 \widetilde\Omega\left(
 \max\left\{
  \frac{\sigma_1^4D_p}{M_{K_{\max}}^2},
  \frac{\sigma_1^8K_{\max}D_p}
  {\varepsilon^2\eta^4\delta_{\mathrm{gap}}(K_{\max})^2}
 \right\}
 \right),
\]
where
\[
 M_{K_{\max}}
 :=
 \min\left\{
  \sigma^2,\,
  \sigma_{K_{\max}}^2,\,
  \delta_{\mathrm{gap}}(K_{\max}),\,
  \frac{\eta^2\delta_{\mathrm{gap}}(K_{\max})}
  {\sigma_1^2\sqrt{K_{\max}}}
 \right\}.
\]

\label{lem:move-forward-weighted}
Let \(0 \leq \tau < \tau' \leq T\) and set \(\Delta := \tau' - \tau\).
For the forward OU process in \(\mathbb{R}^K\) with rate matrix
\(\Lambda = \mathrm{diag}(\lambda_1,\ldots,\lambda_K)\), all \(\lambda_i > 0\):
\begin{equation}\label{eq:weighted-movement}
 \mathbb{E}\bigl[\|U_{\tau'} - U_\tau\|^2_\Lambda\bigr]
 \;\leq\;
 4\Bigl[\lambda_{\max}^2\Delta^2
 \Bigl(m_{2,\Lambda}^2 + \sigma^2\,\mathrm{tr}(\Lambda)\Bigr)
 + \sigma^2\Delta\,\mathrm{tr}(\Lambda^2)\Bigr].
\end{equation}

\label{lem:trace_aware_weighted}
Let $Y\sim q$ on $\mathbb{R}^d$ with density $q=e^{-V}/Z$, where
$V\in C^2(\mathbb{R}^d)$, and assume that the score
$s(y):=\nabla\log q(y)$ is $L$-Lipschitz. Assume also that the differentiations
under the integral sign, integrations by parts, and conditional Brascamp-Lieb
steps used below are justified; for instance, this holds under standard
smoothness and tail-decay conditions ensuring that the required boundary terms
vanish.
Let $D=\mathrm{diag}(\rho_1,\dots,\rho_d)$ with
$\rho_i\in[1-\zeta,1)$, $\zeta\in(0,1/2]$.
Define
\[
\Sigma:=\sigma^2(I-D^2),
\qquad
Y':=DY,
\qquad
X:=Y'+\varepsilon,
\qquad
\varepsilon\sim\mathcal{N}(0,\Sigma)
\text{ independent of }Y.
\]
Let $\tilde{q}:=\mathrm{Law}(X)$ and
$\tilde{s}(u):=\nabla\log\tilde{q}(u)$.
Let $\bm{\Lambda}=\mathrm{diag}(\lambda_1,\dots,\lambda_d)$ with
all $\lambda_i>0$, and let
$\kappa:=\lambda_{\max}/\lambda_{\min}$.
If
\begin{equation}
16\sqrt{\kappa}\,L\sigma^2\zeta\le 1,
\label{eq:small-step-weighted}
\end{equation}
then for every $u\in\mathbb{R}^d$,
\begin{equation}
\|\tilde{s}(u)-s(u)\|_{\bm{\Lambda}}
\le C(\kappa)\Bigl(
 L\zeta\|u\|_{\bm{\Lambda}}
 +(1+L\sigma^2)\zeta\|s(u)\|_{\bm{\Lambda}}
 +L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}
\Bigr),
\label{eq:weighted-perturb}
\end{equation}
where $C(\kappa)>0$ is a constant depending only on
$\kappa$ and universal constants. If moreover
\[
 \zeta\le\min\{1/8,\,1/(128\sqrt\kappa\,L\sigma^2)\},
\]
then, after increasing \(C(\kappa)\), one may replace
\(\|s(u)\|_\Lambda\) by the later-time score
\(\|\tilde s(u)\|_\Lambda\):
\begin{equation}
\|\tilde{s}(u)-s(u)\|_{\bm{\Lambda}}
\le C(\kappa)\Bigl(
 L\zeta\|u\|_{\bm{\Lambda}}
 +(1+L\sigma^2)\zeta\|\tilde s(u)\|_{\bm{\Lambda}}
 +L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}
\Bigr).
\label{eq:weighted-perturb-later}
\end{equation}

\medskip\noindent

Let $q_{Y'}$ be the density of $Y'=DY$.
By the change-of-variables formula,
$q_{Y'}(u)=|\det D|^{-1}q(D^{-1}u)$, hence
$s_{Y'}(u):=\nabla\log q_{Y'}(u)=D^{-1}s(D^{-1}u)$.
Since $\rho_i\in[1-\zeta,1)$ and $\zeta\le 1/2$,
we have $\rho_i\ge 1/2$, so
$\|D^{-1}\|_{\mathrm{op}}\le 2$ and
$\|D^{-1}-I\|_{\mathrm{op}}\le 2\zeta$.

We bound $\|s_{Y'}(u)-s(u)\|_{\bm{\Lambda}}$.
Since $s$ is $L$-Lipschitz in the Euclidean norm,
converting to the $\bm{\Lambda}$-norm using
$\|v\|_{\bm{\Lambda}}\le\sqrt{\lambda_{\max}}\|v\|$
and $\|v\|\le\|v\|_{\bm{\Lambda}}/\sqrt{\lambda_{\min}}$:
\[
\|s(D^{-1}u)-s(u)\|_{\bm{\Lambda}}
\le\sqrt{\lambda_{\max}}\|s(D^{-1}u)-s(u)\|
\le\sqrt{\lambda_{\max}}\,L\,\|D^{-1}u-u\|
\le\sqrt{\kappa}\,L\,\|(D^{-1}-I)u\|_{\bm{\Lambda}}.
\]
Since $D^{-1}-I$ is diagonal with entries
$|\rho_i^{-1}-1|\le 2\zeta$:
\[
\|(D^{-1}-I)u\|_{\bm{\Lambda}}^2
=\sum_i\lambda_i(\rho_i^{-1}-1)^2 u_i^2
\le 4\zeta^2\|u\|_{\bm{\Lambda}}^2,
\]
so $\|(D^{-1}-I)u\|_{\bm{\Lambda}}\le 2\zeta\|u\|_{\bm{\Lambda}}$.
For the second term,
$\|D^{-1}s(u)-s(u)\|_{\bm{\Lambda}}
\le\|D^{-1}-I\|_{\mathrm{op}}\|s(u)\|_{\bm{\Lambda}}
\le 2\zeta\|s(u)\|_{\bm{\Lambda}}$.
Therefore:
\begin{align}
\|s_{Y'}(u)-s(u)\|_{\bm{\Lambda}}
&\le\|D^{-1}\|_{\mathrm{op}}
 \|s(D^{-1}u)-s(u)\|_{\bm{\Lambda}}
 +\|D^{-1}-I\|_{\mathrm{op}}\|s(u)\|_{\bm{\Lambda}}
\nonumber\\
&\le 2\cdot 2\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +2\zeta\|s(u)\|_{\bm{\Lambda}}
\nonumber\\
&= 4\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +2\zeta\|s(u)\|_{\bm{\Lambda}}.
\label{eq:step1-w}
\end{align}
In particular:
\begin{equation}
\|s_{Y'}(u)\|_{\bm{\Lambda}}
\le 4\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +(1+2\zeta)\|s(u)\|_{\bm{\Lambda}}.
\label{eq:syprime-bound-w}
\end{equation}

For all $u,v\in\mathbb{R}^d$:
\[
\|s_{Y'}(u)-s_{Y'}(v)\|_{\bm{\Lambda}}
\le\sqrt{\lambda_{\max}}
 \|s_{Y'}(u)-s_{Y'}(v)\|
\le\sqrt{\lambda_{\max}}\,L'
 \|u-v\|
\le\sqrt{\kappa}\,L'\|u-v\|_{\bm{\Lambda}},
\]
where $L'\le 4L$ from the Euclidean proof.
Denote
\begin{equation}
L'_\Lambda:=4\sqrt{\kappa}\,L,
\label{eq:Lprime-w}
\end{equation}
so $s_{Y'}$ is $L'_\Lambda$-Lipschitz in the
$\bm{\Lambda}$-norm.

Since $\Sigma\succ 0$, differentiating
$\tilde{q}(u)=\int q_{Y'}(y)\varphi_\Sigma(u-y)\,dy$
gives:
\[
\tilde{s}(u)
=-\Sigma^{-1}\bar\varepsilon,
\qquad
\tilde{s}(u)=\mathbb{E}_{\pi_u}[s_{Y'}(u-\varepsilon)],
\]
where $\bar\varepsilon:=\mathbb{E}_{\pi_u}[\varepsilon]$
and $\pi_u$ is the posterior of $\varepsilon:=u-Y'$
given $X=u$.
These are identical to Lemma~\ref{lem:score-perturb}.

The potential $V_u(\varepsilon)
:=-\log q_{Y'}(u-\varepsilon)
+\frac{1}{2}\varepsilon^\top\Sigma^{-1}\varepsilon$
satisfies $\nabla^2 V_u\succeq\Sigma^{-1}-L'I$.
Using $L'_\Lambda\|\Sigma\|_{\mathrm{op}}
\le 4\sqrt{\kappa}\,L\cdot 2\sigma^2\zeta
=8\sqrt{\kappa}\,L\sigma^2\zeta\le\tfrac{1}{2}$
(from assumption~\eqref{eq:small-step-weighted}),
and $L'\le 4L\le L'_\Lambda/\sqrt{\kappa}$,
we have $L'\|\Sigma\|_{\mathrm{op}}\le 1/2$, so
$\nabla^2 V_u\succeq\frac{1}{2}\Sigma^{-1}$.
By the Brascamp-Lieb inequality,
$\operatorname{Cov}_{\pi_u}(\varepsilon)\preceq 2\Sigma$.
In the $\bm{\Lambda}$-norm, using the diagonal structure
of both $\bm{\Lambda}$ and $\Sigma$:
\[
\mathbb{E}_{\pi_u}\|\varepsilon-\bar\varepsilon\|_{\bm{\Lambda}}^2
=\sum_i\lambda_i\mathbb{E}_{\pi_u}
 [(\varepsilon_i-\bar\varepsilon_i)^2]
\le 2\sum_i\lambda_i\Sigma_{ii}
=2\operatorname{tr}(\bm{\Lambda}\Sigma).
\]
By Jensen:
\begin{equation}
\mathbb{E}_{\pi_u}\|\varepsilon\|_{\bm{\Lambda}}
\le\|\bar\varepsilon\|_{\bm{\Lambda}}
 +\sqrt{2\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\label{eq:Eeps-w}
\end{equation}

Since $\bm{\Lambda}$ and $\Sigma$ are both diagonal,
they commute:
\[
\|\Sigma z\|_{\bm{\Lambda}}
=\|\bm{\Lambda}^{1/2}\Sigma z\|
=\|\Sigma\bm{\Lambda}^{1/2}z\|
\le\|\Sigma\|_{\mathrm{op}}\|\bm{\Lambda}^{1/2}z\|
=\|\Sigma\|_{\mathrm{op}}\|z\|_{\bm{\Lambda}}.
\]
Using $\bar\varepsilon
=-\Sigma\mathbb{E}_{\pi_u}[s_{Y'}(u-\varepsilon)]$
and the $\bm{\Lambda}$-Lipschitz bound on $s_{Y'}$:
\[
\|\bar\varepsilon\|_{\bm{\Lambda}}
\le\|\Sigma\|_{\mathrm{op}}
 \mathbb{E}_{\pi_u}\|s_{Y'}(u-\varepsilon)\|_{\bm{\Lambda}}
\le\|\Sigma\|_{\mathrm{op}}\Bigl(
 \|s_{Y'}(u)\|_{\bm{\Lambda}}
 +L'_\Lambda\mathbb{E}_{\pi_u}\|\varepsilon\|_{\bm{\Lambda}}
\Bigr).
\]
Set $x:=\mathbb{E}_{\pi_u}\|\varepsilon\|_{\bm{\Lambda}}$
and $b:=L'_\Lambda\|\Sigma\|_{\mathrm{op}}
\le 8\sqrt{\kappa}\,L\sigma^2\zeta\le\tfrac{1}{2}$.
Substituting $\|\bar\varepsilon\|_{\bm{\Lambda}}$ into
\eqref{eq:Eeps-w}:
\[
x\le\|\Sigma\|_{\mathrm{op}}\|s_{Y'}(u)\|_{\bm{\Lambda}}
 +b\,x+\sqrt{2\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\]
Since $b\le\tfrac{1}{2}$, rearranging $(1-b)x\le a+c$
with $a=\|\Sigma\|_{\mathrm{op}}\|s_{Y'}(u)\|_{\bm{\Lambda}}$
and $c=\sqrt{2\operatorname{tr}(\bm{\Lambda}\Sigma)}$:
\begin{equation}
\mathbb{E}_{\pi_u}\|\varepsilon\|_{\bm{\Lambda}}
\le 2\|\Sigma\|_{\mathrm{op}}\|s_{Y'}(u)\|_{\bm{\Lambda}}
 +2\sqrt{2\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\label{eq:Eeps-final-w}
\end{equation}

Using the denoising identity,
the $\bm{\Lambda}$-Lipschitz bound~\eqref{eq:Lprime-w},
and~\eqref{eq:Eeps-final-w}:
\begin{align*}
\|\tilde{s}(u)-s_{Y'}(u)\|_{\bm{\Lambda}}
&=\|\mathbb{E}_{\pi_u}[s_{Y'}(u-\varepsilon)
 -s_{Y'}(u)]\|_{\bm{\Lambda}}\\
&\le L'_\Lambda\mathbb{E}_{\pi_u}\|\varepsilon\|_{\bm{\Lambda}}\\
&\le 2L'_\Lambda\|\Sigma\|_{\mathrm{op}}
 \|s_{Y'}(u)\|_{\bm{\Lambda}}
 +2L'_\Lambda\sqrt{2\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\end{align*}
Retaining the full $\zeta$ factor:
\[
2L'_\Lambda\|\Sigma\|_{\mathrm{op}}
\le 16\sqrt{\kappa}\,L\sigma^2\zeta,
\qquad
2L'_\Lambda
\le 8\sqrt{\kappa}\,L.
\]
Therefore:
\begin{equation}
\|\tilde{s}(u)-s_{Y'}(u)\|_{\bm{\Lambda}}
\le 16\sqrt{\kappa}\,L\sigma^2\zeta
 \|s_{Y'}(u)\|_{\bm{\Lambda}}
 +C_1\sqrt{\kappa}\,L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)},
\label{eq:step6-w}
\end{equation}
for a universal constant $C_1>0$.

Substituting~\eqref{eq:syprime-bound-w}
into~\eqref{eq:step6-w}:
\begin{align*}
\|\tilde{s}(u)-s_{Y'}(u)\|_{\bm{\Lambda}}
&\le 16\sqrt{\kappa}\,L\sigma^2\zeta\Bigl(
 4\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +(1+2\zeta)\|s(u)\|_{\bm{\Lambda}}
 \Bigr)
 +C_1\sqrt{\kappa}\,L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}\\
&= 64\kappa\,L^2\sigma^2\zeta^2\|u\|_{\bm{\Lambda}}
 +16\sqrt{\kappa}\,L\sigma^2(1+2\zeta)\zeta
 \|s(u)\|_{\bm{\Lambda}}
 +C_1\sqrt{\kappa}\,L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\end{align*}
Using $16\sqrt{\kappa}\,L\sigma^2\zeta\le 1$
and $\zeta\le 1/2$:
\[
64\kappa\,L^2\sigma^2\zeta^2
=4\sqrt{\kappa}\,L\zeta
 \cdot 16\sqrt{\kappa}\,L\sigma^2\zeta
\le 4\sqrt{\kappa}\,L\zeta,
\]
\[
16\sqrt{\kappa}\,L\sigma^2(1+2\zeta)\zeta
\le 32\sqrt{\kappa}\,L\sigma^2\zeta.
\]
Adding~\eqref{eq:step1-w} via the triangle inequality:
\begin{align*}
\|\tilde{s}(u)-s(u)\|_{\bm{\Lambda}}
&\le\|\tilde{s}(u)-s_{Y'}(u)\|_{\bm{\Lambda}}
 +\|s_{Y'}(u)-s(u)\|_{\bm{\Lambda}}\\
&\le\Bigl(
 4\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +32\sqrt{\kappa}\,L\sigma^2\zeta
  \|s(u)\|_{\bm{\Lambda}}
 +C_1\sqrt{\kappa}\,L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}
 \Bigr)\\
&\quad+\Bigl(
 4\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +2\zeta\|s(u)\|_{\bm{\Lambda}}
 \Bigr)\\
&= 8\sqrt{\kappa}\,L\zeta\|u\|_{\bm{\Lambda}}
 +(32\sqrt{\kappa}\,L\sigma^2+2)\zeta
 \|s(u)\|_{\bm{\Lambda}}
 +C_1\sqrt{\kappa}\,L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}.
\end{align*}
Since $32\sqrt{\kappa}\,L\sigma^2+2
\le C(\kappa)(1+L\sigma^2)$ for a constant
$C(\kappa)$ depending only on $\kappa$ (one can take
$C(\kappa)=c\sqrt\kappa$ for a universal $c$, so $C(\kappa)$ does
not decrease in $\kappa$),
and absorb $8\sqrt{\kappa}$ and $C_1\sqrt{\kappa}$
into $C(\kappa)$:
\[
\|\tilde{s}(u)-s(u)\|_{\bm{\Lambda}}
\le C(\kappa)\Bigl(
 L\zeta\|u\|_{\bm{\Lambda}}
 +(1+L\sigma^2)\zeta\|s(u)\|_{\bm{\Lambda}}
 +L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}
\Bigr).
\]
For the later-time-score version, write the display before the last one
as $\|\tilde s(u)-s(u)\|_{\bm{\Lambda}}\le8\sqrt\kappa L\zeta\|u\|_{\bm{\Lambda}}
+b\|s(u)\|_{\bm{\Lambda}}+C_1\sqrt\kappa L\sqrt{\operatorname{tr}(\bm{\Lambda}\Sigma)}$ with
$b:=(32\sqrt\kappa L\sigma^2+2)\zeta$, and substitute
$\|s(u)\|_{\bm{\Lambda}}\le\|\tilde s(u)\|_{\bm{\Lambda}}
+\|\tilde s(u)-s(u)\|_{\bm{\Lambda}}$. Under
$\zeta\le\min\{1/8,1/(128\sqrt\kappa L\sigma^2)\}$ we have $b\le1/2$,
so the last term can be moved to the left-hand side at the cost of a factor
$2$, which is absorbed into $C(\kappa)$.

\label{def:broken}
For $A>0$, a breakpoint $b\ge1$ and exponents $\beta_1\le\beta_2$, the continuous broken power law is
\[
\sigma_i^2 \;=\;
\begin{cases}
A\, i^{-\beta_1}, & i\le b,\\[2pt]
A\, b^{\beta_2-\beta_1}\, i^{-\beta_2}, & i> b,
\end{cases}
\]
or equivalently
$\log\sigma_i^2=\log A-\beta_1\log i-(\beta_2-\beta_1)(\log i-\log b)_+$.
It decays like $i^{-\beta_1}$ before the breakpoint and like $i^{-\beta_2}$ after it, and is continuous at $i=b$. The
case $\beta_1=\beta_2$ is the exact power law~(2).
